('<div class="fn-env" id="sauceEnv"><div class="fn-flap" aria-hidden="true"></div><span class="fn-seal" aria-hidden="true">N</span><span class="fn-sk">Streng geheim</span><div class="fn-et">Nonnas Tomatensoße</div><p class="fn-eq">Piano, piano! Erst eine Frage: Was sagt der Pizzaiolo, wenn du ihn nach seinem Geheimnis fragst?</p><div class="fn-ans"><button data-a="0">„Fuoco e pazienza.“</button><button data-a="1">„Il tempo e l’impasto.“</button><button data-a="0">„La farina giusta.“</button></div><p class="fn-eh" id="sauceHint" aria-live="polite"></p><button class="fn-elink" id="sauceStory" hidden>Zur Geschichte ›</button></div>', '<div class="fn-env" id="sauceEnv"><div class="fn-flap" aria-hidden="true"></div><span class="fn-seal" aria-hidden="true">N</span><span class="fn-sk">Secret</span><div class="fn-et">Nonna’s tomato sauce</div><p class="fn-eq">Not so fast. One question first: what does the pizzaiolo say when you ask him for his secret?</p><div class="fn-ans"><button data-a="0">“Fuoco e pazienza.”</button><button data-a="1">“Il tempo e l’impasto.”</button><button data-a="0">“La farina giusta.”</button></div><p class="fn-eh" id="sauceHint" aria-live="polite"></p><button class="fn-elink" id="sauceStory" hidden>To the story ›</button></div>'),
